// Build Phase1 payload from scenario POST body (Evolution API or Meta WA format)
const body = $input.first().json.body || $input.first().json;
const scenario = body.scenario || 'custom';
const data = body.data || body;
const key = data.key || {};
const waMsg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const phone = String(body.phone || key.remoteJid?.replace('@s.whatsapp.net','') || waMsg?.from || '').trim();
const providerMessageId = body.provider_message_id || key.id || waMsg?.id || null;
const text = body.text || body.textContent || waMsg?.text?.body || '';
return [{ json: {
  scenario,
  phone,
  textContent: text,
  remoteJid: phone ? phone + '@s.whatsapp.net' : null,
  phase1: {
    phone,
    provider_message_id: providerMessageId ? String(providerMessageId) : null,
    channel: body.channel || 'whatsapp',
    message_text: text,
    message_type: body.message_type || 'text',
    metadata: { scenario, test: true }
  }
}}];

const r = $input.first()?.json;
const norm = $('Scenario Normalize').first()?.json || {};
if (!r) {
  return [{ json: { scenario: norm.scenario, proceed: false, stop_reason: 'empty_inbound_result' } }];
}
return [{ json: {
  scenario: norm.scenario,
  proceed: r.proceed,
  stop_reason: r.stop_reason,
  lead_id: r.lead_id,
  customer_id: r.customer_id,
  conversation_id: r.conversation_id,
  provider_message_id: r.phase1?.provider_message_id
}}];
